  unit: string;
  value: number;
  at: number;
}

interface ParsedReading {
  channel: string;
  millivolts: number;
  at: number;
}

interface ChannelSummary {
  count: number;
  min: number;
  max: number;
  worst: string;
}

export interface BatchResult {
  ok: boolean;
  error?: string;
  readings?: number;
  labels?: string[];
  channels?: Record<string, ChannelSummary>;
  alerts?: string[];
  report?: string;
}

const MAX_READINGS = 500;
const UNITS = ["uV", "mV", "V"];

export function processBatch(raw: unknown): BatchResult {
  const batchError = validateBatch(raw);
  if (batchError !== null) {
    return { ok: false, error: batchError };
  }
  const entries = (raw as { readings: unknown[] }).readings;

  const labels: string[] = [];
  const alerts: string[] = [];
  const channels: Record<string, ChannelSummary> = {};
  let worst = "standby";

  // Single pass over the raw entries: normalize, label, alert, and summarize
  // all at once instead of iterating the list multiple times.
  for (let index = 0; index < entries.length; index++) {
    const outcome = parseReading(entries[index], index);
    if (typeof outcome === "string") {
      return { ok: false, error: outcome };
    }
    const reading = outcome;
    const label = classifySignal(reading.millivolts);

    labels.push(label);
    if (severityRank(label) > severityRank(worst)) {
      worst = label;
    }

    const alert = alertFor(reading);
    if (alert !== null) {
      alerts.push(alert);
    }

    accumulate(channels, reading, label);
  }

  const report = buildReport(entries.length, Object.keys(channels).length, alerts.length, worst);
  return { ok: true, readings: entries.length, labels, channels, alerts, report };
}

function validateBatch(raw: unknown): string | null {
  if (typeof raw !== "object" || raw === null) {
    return "malformed batch";
  }
  const batch = raw as Record<string, unknown>;
  if (!Array.isArray(batch.readings)) {
    return "missing readings";
  }
  if (batch.readings.length === 0) {
    return "empty batch";
  }
  if (batch.readings.length > MAX_READINGS) {
    return "batch too large";
  }
  return null;
}

// Parses and normalizes a single entry into the values actually used downstream.
function parseReading(entry: unknown, index: number): ParsedReading | string {
  if (typeof entry !== "object" || entry === null) {
    return "reading " + index + ": malformed";
  }
  const record = entry as Record<string, unknown>;
  if (typeof record.channel !== "string" || record.channel.length === 0) {
    return "reading " + index + ": bad channel";
  }
  const unit = record.unit as string;
  if (UNITS.indexOf(unit) < 0) {
    return "reading " + index + ": bad unit";
  }
  const value = record.value as number;
  if (!Number.isInteger(value)) {
    return "reading " + index + ": bad value";
  }
  const at = record.at as number;
  if (!isNonNegativeInt(at)) {
    return "reading " + index + ": bad timestamp";
  }
  return { channel: record.channel, millivolts: normalizeValue(unit, value), at };
}

function isNonNegativeInt(value: unknown): boolean {
  return Number.isInteger(value) && (value as number) >= 0;
}

function normalizeValue(unit: string, value: number): number {
  if (unit === "V") {
    return value * 1000;
  }
  if (unit === "uV") {
    return Math.trunc(value / 1000);
  }
  return value;
}

export function classifySignal(millivolts: number): string {
  if (millivolts >= 0 && millivolts < 50) {
    return "standby";
  }
  if (millivolts >= 50 && millivolts < 200) {
    return "idle";
  }
  if (millivolts >= 200 && millivolts < 600) {
    return "active";
  }
  if (millivolts >= 600 && millivolts < 900) {
    return "loaded";
  }
  if (millivolts >= 900) {
    return "critical";
  }
  return "negative";
}

function severityRank(label: string): number {
  if (label === "negative") {
    return 5;
  }
  if (label === "critical") {
    return 4;
  }
  if (label === "loaded") {
    return 3;
  }
  if (label === "active") {
    return 2;
  }
  if (label === "idle") {
    return 1;
  }
  return 0;
}

// Returns the alert string for a reading, or null when none applies.
function alertFor(reading: ParsedReading): string | null {
  if (reading.millivolts >= 900) {
    return reading.channel + ":critical";
  }
  if (reading.millivolts < 0) {
    return reading.channel + ":negative";
  }
  if (reading.millivolts >= 600 && reading.millivolts < 900) {
    return reading.channel + ":loaded";
  }
  return null;
}

function accumulate(channels: Record<string, ChannelSummary>, reading: ParsedReading, label: string): void {
  const existing = channels[reading.channel];
  if (existing === undefined) {
    channels[reading.channel] = { count: 1, min: reading.millivolts, max: reading.millivolts, worst: label };
    return;
  }
  existing.count = existing.count + 1;
  if (reading.millivolts < existing.min) {
    existing.min = reading.millivolts;
  }
  if (reading.millivolts > existing.max) {
    existing.max = reading.millivolts;
  }
  if (severityRank(label) > severityRank(existing.worst)) {
    existing.worst = label;
  }
}

function buildReport(readingCount: number, channelCount: number, alertCount: number, worst: string): string {
  return "readings=" + readingCount + ";channels=" + channelCount + ";alerts=" + alertCount + ";worst=" + worst;
}

