    });
  }
  return { readings };
}
function same(a,b){
  return JSON.stringify(a)===JSON.stringify(b);
}

// fixed interesting cases
const cases=[
  null, 42, 'x', {}, {readings:[]}, {readings:'x'},
  ...Array.from({length:501},(_,i)=>({readings:[{channel:'a',unit:'V',value:1,at:0}]})),
];
// fuzz
for(let t=0;t<200000;t++) cases.push(rnd());

let bad=0;
for(const c of cases){
  const a=orig.processBatch(c), b=nw.processBatch(c);
  if(!same(a,b)){ bad++; if(bad<20) console.log('MISMATCH', JSON.stringify(c), JSON.stringify(a), JSON.stringify(b)); }
}
console.log('checked',cases.length,'cases mismatches=',bad);
